<h2>{%= tax_escape(__("VAT Return Table")) %}</h2>
<div class="tax-context">
{%= tax_escape(tax_filters.company || "") %} | {%= tax_escape(tax_filters.from_date || "") %} — {%= tax_escape(tax_filters.to_date || "") %}
