 | {%= tax_escape(__("Voucher Type")) %}: {%= tax_escape(__(tax_filters.voucher_type || "All")) %}
 | {%= tax_escape(__("Party")) %}: {%= tax_escape(tax_filters.party || __("All")) %}
 | {%= tax_escape(__("Voucher No")) %}: {%= tax_escape(tax_filters.invoice_no || __("All")) %}
</div>
{% var tax_return=tax_meta.declaration; if (!tax_return) { %}
<p class="notice">{%= tax_escape(__("No report data. Refresh the report before printing.")) %}</p>
{% } else { %}
<table class="declaration"><thead><tr><th>{%= tax_escape(__("Description")) %}</th><th>{%= tax_escape(__("Amount")) %}</th><th>{%= tax_escape(__("Tax Adjustment Amount")) %}</th><th>{%= tax_escape(__("VAT Amount")) %}</th></tr></thead><tbody>
