{% } %}
<tr class="{%= r.is_total ? 'subtotal' : '' %}"><td>{%= r.number %}. {%= tax_escape(r.label) %}</td><td class="numeric">{%= tax_num(r.amount) %}</td><td class="numeric">{%= tax_num(r.adjustment) %}</td><td class="numeric">{%= tax_num(r.tax) %}</td></tr>
