for(var i=0; i<tax_foot.length; i++) { %}
<tr class="{%= i===3 ? 'grand_total' : '' %}"><td>{%= tax_escape(__(tax_foot[i][0])) %}</td><td colspan="3" class="numeric">{%= tax_num(tax_foot[i][1]) %}</td></tr>
