</tbody></table>
<p class="notice">
{%= tax_escape(tax_return.complete ? __('Classification complete for the entered data; review before filing.') : __('Incomplete draft: {0} vouchers require review. Incomplete boxes: {1}.',[tax_return.pending.length,tax_return.missing_boxes.join(', ')])) %}
